using System.ComponentModel;
using System.Net;
using System.Text.RegularExpressions;
using Microsoft.Extensions.AI;
using OpenAI;

// ── State for the note-taking tool ──────────────────────────────────────────
var notes = new List<string>();

// ── Define tools the agent can call ─────────────────────────────────────────
var searchTool = AIFunctionFactory.Create(
    SearchWebAsync, "search_web",
    "Searches the web for information on a query and returns relevant snippets.");

var addNoteTool = AIFunctionFactory.Create(
    AddNote, "add_note",
    "Saves a research note with key findings to reference later.");

var getNotesTool = AIFunctionFactory.Create(
    GetNotes, "get_notes",
    "Retrieves all saved research notes.");

// ── Build the chat client with automatic function invocation ────────────────
var apiKey = Environment.GetEnvironmentVariable("OPENAI_API_KEY")
    ?? throw new InvalidOperationException(
        "Set the OPENAI_API_KEY environment variable before running.");

var model = Environment.GetEnvironmentVariable("OPENAI_MODEL") ?? "gpt-4o-mini";

IChatClient client = new OpenAIClient(apiKey)
    .GetChatClient(model)
    .AsIChatClient()
    .AsBuilder()
    .UseFunctionInvocation()
    .Build();

var chatOptions = new ChatOptions
{
    Tools = [searchTool, addNoteTool, getNotesTool]
};

// ── Prompt the user for a topic ─────────────────────────────────────────────
Console.Write("Enter a research topic: ");
var topic = Console.ReadLine()?.Trim();
if (string.IsNullOrEmpty(topic))
{
    Console.WriteLine("No topic provided. Exiting.");
    return;
}

Console.WriteLine($"\n📚 Researching: {topic}\n");

var messages = new List<ChatMessage>
{
    new(ChatRole.System, """
        You are a research agent. Given a topic you must:
        1. Search the web several times with varied queries to gather broad information.
        2. Save the key findings as notes using the add_note tool.
        3. After gathering enough information, call get_notes and write a well-structured
           summary with clear headings and citations where possible.

        Perform at least 3 different searches before summarizing.
        """),
    new(ChatRole.User,
        $"Research the following topic and provide a comprehensive summary:\n\n{topic}")
};

Console.WriteLine("Agent is working…\n");

var response = await client.GetChatCompletionAsync(messages, chatOptions);

Console.WriteLine("\n═══════════════════════════════════════");
Console.WriteLine("          RESEARCH SUMMARY");
Console.WriteLine("═══════════════════════════════════════\n");
Console.WriteLine(response.Message.Text);

// ── Tool implementations ────────────────────────────────────────────────────

[Description("Searches the web for a given query")]
async Task<string> SearchWebAsync(
    [Description("The search query")] string query)
{
    Console.WriteLine($"  🔍 Searching: \"{query}\"");
    using var http = new HttpClient();
    http.DefaultRequestHeaders.UserAgent.ParseAdd("ResearchAgent/1.0");

    try
    {
        var encoded = Uri.EscapeDataString(query);
        var html = await http.GetStringAsync(
            $"https://lite.duckduckgo.com/lite/?q={encoded}");
        var snippets = ExtractSnippets(html);
        return snippets.Length > 0
            ? snippets
            : $"No clear results for '{query}'. Try a different query.";
    }
    catch (Exception ex)
    {
        return $"Search failed ({ex.Message}). Try a different query.";
    }
}

[Description("Saves a research note")]
string AddNote([Description("The note content to save")] string note)
{
    notes.Add(note);
    Console.WriteLine($"  📝 Note saved ({notes.Count} total)");
    return $"Note saved. You now have {notes.Count} note(s).";
}

[Description("Gets all saved notes")]
string GetNotes()
{
    if (notes.Count == 0) return "No notes saved yet.";
    Console.WriteLine($"  📋 Retrieving {notes.Count} note(s)");
    return string.Join("\n\n---\n\n",
        notes.Select((n, i) => $"Note {i + 1}:\n{n}"));
}

// ── Helper ──────────────────────────────────────────────────────────────────

static string ExtractSnippets(string html)
{
    var text = Regex.Replace(html, "<[^>]+>", " ");
    text = Regex.Replace(text, @"\s+", " ");
    text = WebUtility.HtmlDecode(text);
    return text.Length > 3000 ? text[..3000].Trim() : text.Trim();
}

